const rng = (s) => () => ((s = (s * 16807) % 2147483647) / 2147483647); // pseudoaleatório com seed fixa
const sceneDur = 4; // duração da cena em s (troque pela real)

// items = círculos com borda clara; origem no centro da cena
const r = rng(64);
items.forEach((b) => {
  // rise = segundos para atravessar a tela; cada bolha parte de uma altura sorteada e sobe a cena inteira
  const x0 = (r() - 0.5) * 900, s = 0.4 + r() * 0.8, rise = 5 + r() * 2.5, y0 = 1000 - r() * 1400;
  const speed = 2000 / rise, pop = (y0 + 840) / speed; // instante em que chega ao alto e estoura
  const life = Math.min(sceneDur, pop);
  tl.fromTo(b, { y: y0, scale: s, opacity: 0.8 }, { y: y0 - speed * life, duration: life, ease: "none" }, t);
  tl.fromTo(b, { x: x0 - 20 }, { x: x0 + 20, duration: 0.8, ease: "sine.inOut", yoyo: true, repeat: Math.max(0, Math.floor(life / 0.8) - 1) }, t);
  if (pop + 0.12 <= sceneDur) tl.fromTo(b, { scale: s, opacity: 0.8 }, { scale: s * 1.4, opacity: 0, duration: 0.12, immediateRender: false }, t + pop);
});

