const rng = (s) => () => ((s = (s * 16807) % 2147483647) / 2147483647); // pseudoaleatório com seed fixa

// items = [líder, ...partículas]; todos na mesma linha de origem
const [lead, ...dots] = items, r = rng(9), x0 = -450, x1 = 450, dur = 1.2;
